import{_ as t,o as i,c as l,ac as o}from"./chunks/framework.Bzw8ikz_.js";const r="/hubHooks/assets/gitFlow.D49Q6IZD.jpg",d="/hubHooks/assets/1.BUFse1ou.png",h=JSON.parse('{"title":"5大分支","description":"","frontmatter":{},"headers":[],"relativePath":"operations/git/gitFlow.md","filePath":"operations/git/gitFlow.md","lastUpdated":1774322613000}'),a={name:"operations/git/gitFlow.md"};function s(c,e,n,g,u,p){return i(),l("div",null,[...e[0]||(e[0]=[o('<p>[_GitFlow是一种非常经典的分支管理和发布模型，常用于管理大型项目。</p><p>它特别适合管理有固定发布周期、需要并行开发多个功能以及需要长期维护多个版本的项目。 <img src="'+r+'" alt="img"></p><h1 id="_5大分支" tabindex="-1">5大分支 <a class="header-anchor" href="#_5大分支" aria-label="Permalink to &quot;5大分支&quot;">​</a></h1><p>通常包含五大分支</p><ol><li>主要分支 <ul><li>主分支（master/main）</li><li>开发分支（dev）</li></ul></li><li>辅助/临时分支 <ul><li>功能分支（feature）</li><li>发布分支（release）</li><li>热修复分支（hotfix*）</li></ul></li></ol><p><strong>细说5大分支：</strong></p><ol><li>主分支（master/main） <ul><li>作用：存放<strong>稳定、可随时部署到生产环境</strong>的代码</li><li>特点： <ul><li>分支上的的每一次提交都对应一个正式版本的发布</li><li><strong>不允许在此分支上直接开发</strong></li><li>通常会被打上版本标签（如<code>v1.0.0</code>）</li></ul></li></ul></li><li>开发分支(develop) <ul><li>作用：存放最<strong>新开发成果</strong>的集成分支，是功能开发的集线器。</li><li>特点： <ul><li>当<code>develop</code>分支上的代码达到稳定状态并准备发布时，会合并到<code>main</code>分支。</li><li>main所有功能分支、发布分支都从develop分支拉取。</li></ul></li></ul></li><li>功能分支(feature) <ul><li>来源：dev</li><li>合并目标：dev</li><li>命名惯例：<code>feature/user-authentication</code></li><li>作用：开发新分支</li><li>生命周期 <ul><li>从<code>dev</code>分支拉取代码</li><li>开发完成后合并到<code>dev</code>分支</li><li><strong>合并后该分支通常被删除</strong></li></ul></li></ul></li><li>发布分支（release） <ul><li>来源：dev</li><li>合并目标：<code>dev</code>和<code>main</code>分支</li><li>命名惯例：<code>release/1.2.0</code></li><li>作用：为发布新版本做准备。在此分支上<strong>只做Bug修复、生成版本号、整理文档等发布准备工作，不 再添加新功能。</strong></li><li>生命周期 <ul><li>当 <code>develop</code>分支的功能足够进行一次发布时，从<code>develop</code>拉出 <code>release</code>分支。</li><li>在此分支上进行最后的测试和修复。</li><li>准备就绪后，将release分支合并到main分支并打上版本标签。</li><li>同时，还必须合并回 <code>develop</code>分支，因为<code>release</code>分支上的修复可能在develop 分支上不存在。</li></ul></li></ul></li><li>热修复分支（hotfix*） <ul><li>来源：main</li><li>合并目标：<code>dev</code>和<code>main</code></li><li>命名惯例：<code>hotfix/1.2.1</code>,<code>hotfix/critical-security-patch</code></li><li>作用：快速修复生产环境(main分支)上的紧急Bug。</li><li>生命周期 <ul><li>从<code>main</code>分支上出现Bug的提交点(通常是最近的标签)拉取。</li><li>修复完成后，合并回 <code>main</code>分支并打上新的版本标签(如main v1.0.1)</li><li><strong>同时，还必须合并回develop分支</strong>，确保修复在后续开发中也生效。</li></ul></li></ul></li></ol><p><img src="'+d+'" alt="流程"></p><h1 id="merge-合并-和rebase-变基" tabindex="-1">merge（合并） 和rebase（变基） <a class="header-anchor" href="#merge-合并-和rebase-变基" aria-label="Permalink to &quot;merge（合并） 和rebase（变基）&quot;">​</a></h1><p><strong>git merge(合并)</strong>:就像用胶水把两条绳子粘在一起。它承认两条分支独立发展的事实，并在汇合点 创建一个新的&quot;合并提交”把两者连起来。 <strong>历史记录是真实的，但可能会显得复杂</strong>。</p><p><strong>git rebase(变基)</strong>:就像把一条绳子拆开，然后接到另一条绳子的最新位置。它通过重新播放提交， 使得历史看起来像是在一条直线上顺序发展的。 <strong>历史记录更简洁，但被改写了</strong>。</p><h1 id="revert和reset" tabindex="-1">revert和reset <a class="header-anchor" href="#revert和reset" aria-label="Permalink to &quot;revert和reset&quot;">​</a></h1><p><strong>git reset</strong>: 通过<strong>移动分支</strong>指针来“删除&quot;提交 从而改写历史。它会让提交从提交历史中消失。</p><p><strong>git revert</strong>: 通过<strong>创建一个新的提交</strong>来抵消(反转)指定提交的更改。它**不会改写历史 而是在历史记录中添加一个新的、反向的提交 **。</p><p>一个简单的比喻:</p><p><strong>git reset</strong>:像在书本上撕掉最后几页，故事直接从更早的地方继续。 <strong>git revert</strong>:像在书本上新写一页，内容是“取消第X页中描述的所有操作&quot;，故事继续发展，但包含了这个&quot;修正&quot;步骤。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>黄金法则:对私有分支用reset，对公共历史用revert</p></div><h1 id="git回退情况" tabindex="-1">Git回退情况 <a class="header-anchor" href="#git回退情况" aria-label="Permalink to &quot;Git回退情况&quot;">​</a></h1><table tabindex="0"><thead><tr><th>情况</th><th>shell</th><th>说明</th></tr></thead><tbody><tr><td>有改动，无add 无commit</td><td>git checkout--文件名</td><td>工作区本次改动撤销</td></tr><tr><td>有改动，有add 无commit</td><td>git reset HEAD 文件名</td><td>从暂存区回退到工作区</td></tr><tr><td>有改动，有add 有commit</td><td>git reset --hard HEAD^</td><td>从本地库回退到工作区</td></tr><tr><td>有改动，有add 有commit 有push</td><td><code>git revert &lt;commit-hash&gt; git push </code></td><td>先恢复再push</td></tr></tbody></table>',19)])])}const v=t(a,[["render",s]]);export{h as __pageData,v as default};
